"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[3729],{60112:t=>{t.exports=JSON.parse('{"tag":{"label":"ai","permalink":"/docs/tags/ai","allTagsPath":"/docs/tags","count":2,"items":[{"id":"introduction/index","title":"How to Use LEIA","description":"LEIA (Learning with an Educational Intelligent Assistant) is a platform that lets instructors design interactive simulations and lets students practise in realistic scenarios with AI support. A LEIA is an AI character with a role, a personality and an exercise behind it. Students talk to it, by text or by voice, and may hand in a solution that the platform grades.","permalink":"/docs/"},{"id":"Team/index","title":"Team","description":"LEIA is maintained by a small team focused on product design, engineering, and documentation.","permalink":"/docs/Team/"}],"unlisted":false}}')}}]);